INSERT INTO faq_entries(question,answer,sort_order,status,created_at,updated_at) SELECT 'O que é o Radar Literário?','Uma rede social para leitores acompanharem suas leituras, registrarem diários, avaliarem livros e descobrirem novas histórias.',1,'published',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq_entries WHERE question='O que é o Radar Literário?');
INSERT INTO faq_entries(question,answer,sort_order,status,created_at,updated_at) SELECT 'Como adiciono um livro à minha estante?','Pesquise a obra no catálogo, abra o detalhe e escolha “Adicionar à estante”. Se ela não existir, envie uma sugestão ao catálogo.',2,'published',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq_entries WHERE question='Como adiciono um livro à minha estante?');
INSERT INTO faq_entries(question,answer,sort_order,status,created_at,updated_at) SELECT 'Como registro meu progresso de leitura?','Na estante, use “Registrar progresso” e informe a página atual. O diário também aparece no feed da comunidade.',3,'published',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq_entries WHERE question='Como registro meu progresso de leitura?');
INSERT INTO faq_entries(question,answer,sort_order,status,created_at,updated_at) SELECT 'Posso avaliar um livro que ainda não comecei?','Não. Para avaliar, o livro precisa estar “Em leitura” ou “Concluído” na sua estante.',4,'published',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq_entries WHERE question='Posso avaliar um livro que ainda não comecei?');
INSERT INTO faq_entries(question,answer,sort_order,status,created_at,updated_at) SELECT 'O que acontece com publicações que contêm spoiler?','Elas ficam ocultas por padrão no feed. Quem quiser ver o conteúdo precisa optar por revelar os spoilers.',5,'published',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq_entries WHERE question='O que acontece com publicações que contêm spoiler?');
INSERT INTO faq_entries(question,answer,sort_order,status,created_at,updated_at) SELECT 'Como denuncio um conteúdo?','Use a opção “Denunciar” na publicação ou no comentário. A equipe de moderação analisa e responde pelo suporte.',6,'published',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq_entries WHERE question='Como denuncio um conteúdo?');
INSERT INTO faq_entries(question,answer,sort_order,status,created_at,updated_at) SELECT 'Rascunho: política de privacidade do perfil','Texto ainda em elaboração; não deve aparecer na lista pública.',7,'draft',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq_entries WHERE question='Rascunho: política de privacidade do perfil');
